blocks = [(1,1,9,[[1,0,1],[1,1,1],[0,1,0]]), (1,7,6,[[0,1,1],[0,1,1],[1,0,0]]), (7,1,3,[[1,0,1],[0,1,1],[0,1,0]]), (7,7,4,[[1,1,1],[0,1,0],[0,1,0]])]
out = [[2]*13 for _ in range(13)]
for r0,c0,color,pat in blocks:
    for i in range(5):
        for j in range(5):
            val=color
            if 0<i<4 and 0<j<4 and pat[i-1][j-1]:
                val=2
            out[r0+i][c0+j]=val
print('\n'.join(' '.join(map(str,row)) for row in out))
print(len(out), set(map(len,out)))
